WHERE event_date BETWEEN '2019-01-01' AND '2019-12-31';

SELECT SUM(expense.cost) AS total_parking_cost
FROM expense
WHERE expense.expense_description = 'Parking';

SELECT id
FROM publisher
WHERE publisher_name = 'Star Trek';

SELECT COUNT(superhero.id) / SUM(superhero.skin_colour_id = 1) AS average
FROM superhero
JOIN colour ON superhero.skin_colour_id = colour.id;

SELECT superhero_name, SUM(height_cm) / COUNT(id) AS average_height
FROM superhero
GROUP BY superhero_name;

SELECT s.full_name
FROM superhero s
WHERE s.superhero_name = 'Alien';

SELECT CAST(SUM(CASE WHEN p.SEX = 'M' AND l.UA <= '8.0' THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN p.SEX = 'F' AND l.UA <= '6.5' THEN 1 ELSE 0 END) AS ratio
FROM Patient p
JOIN Laboratory l ON p.ID = l.ID;

SELECT
  (SELECT COUNT(*) FROM bond WHERE bond_type = ' = ' AND molecule_id IN (SELECT molecule_id FROM molecule WHERE molecule_id = 'TR006')) AS double_bond_count,
  (SELECT CASE WHEN label = '+' THEN 'Yes' ELSE 'No' END FROM molecule WHERE molecule_id IN (SELECT molecule_id FROM molecule WHERE molecule_id = 'TR006')) AS carcinogenic;

SELECT COUNT(DISTINCT UserId) AS NumUsers
FROM badges
WHERE Name = 'Announcer';

SELECT LastEditDate, LastEditorUserId
FROM posts
WHERE Title = 'Detecting a given face in a database of facial images';

SELECT Id
FROM users
WHERE Age = (SELECT MIN(Age) FROM users);

SELECT 100.0 * COUNT(CASE WHEN posts.Score > 50 THEN 1 END) / COUNT(posts.Id) AS percentage
FROM posts
WHERE posts.OwnerUserId = (SELECT users.Id FROM users ORDER BY users.Reputation DESC LIMIT 1);

SELECT SUM(CASE WHEN Currency = 'Euro' THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS Percentage
FROM customers
WHERE Segment = 'KAM';

SELECT district_id, A2
FROM district
WHERE A13 = (SELECT MAX(A13) FROM district);

SELECT CAST(SUM(CASE WHEN major.major_name = 'Finance' THEN 1 ELSE 0 END) AS REAL) / NULLIF(SUM(CASE WHEN major.major_name = 'Physics' THEN 1 ELSE 0 END), 0) AS ratio
FROM member
JOIN major ON member.link_to_major = major.major_id;

SELECT SUM(type = 'Community Service') / COUNT(event_id) * 100 AS percentage
FROM event
WHERE event_date BETWEEN '2019-01-01' AND '2019-12-31';

SELECT superhero.id, superhero.superhero_name, SUM(superhero.height_cm) / COUNT(*) AS average_height
FROM superhero
GROUP BY superhero.id, superhero.superhero_name;

SELECT 100.0 * SUM(CASE WHEN Admission = '+' THEN 1 ELSE 0 END) / COUNT(*) AS inpatient_percentage
FROM Patient
WHERE Birthday BETWEEN '1930-01-01' AND '1940-12-31';

SELECT COUNT(ID) AS patient_count, GROUP_CONCAT(ID) AS patient_ids
FROM Patient
WHERE SEX = 'F' AND strftime('%Y', Birthday) = '1964' AND Admission = '+';

SELECT SUM(CASE WHEN atom.element = 'c' THEN 1 ELSE 0 END) * 100.0 / COUNT(atom.atom_id) AS percentage
FROM atom
WHERE atom.molecule_id IN (SELECT bond.molecule_id FROM bond WHERE bond.bond_type = '=');

SELECT 100.0 * SUM(bond_type = ' = ') / COUNT(bond_id) AS percent
FROM bond
WHERE molecule_id = 'TR047';

SELECT CASE WHEN label = '+' THEN 'carcinogenic' ELSE 'non-carcinogenic' END AS carcinogenic_status
FROM molecule
WHERE molecule_id = 'TR000';

SELECT COUNT(DISTINCT UserId) AS user_count
FROM badges
WHERE Name = 'Announcer';

SELECT CAST(COUNT(CASE WHEN strftime('%Y', CreationDate) = '2010' THEN 1 END) AS REAL) /
       NULLIF(COUNT(CASE WHEN strftime('%Y', CreationDate) = '2011' THEN 1 END), 0) AS ratio
FROM votes;

SELECT DisplayName, Age
FROM users
WHERE Views = (SELECT MAX(Views) FROM users);

SELECT LastEditDate, LastEditorUserId
FROM posts
